# ! [allow (clippy :: all)] # ! [cfg_attr (not (target_os = "linux") , allow (dead_code))] use split_decls_genesis :: ourprelude :: * ; use super :: Mmap ; use alloc :: vec ; use alloc :: vec :: Vec ; use core :: cell :: UnsafeCell ; #[doc = " A simple arena allocator for byte buffers."] pub struct Stash { buffers : UnsafeCell < Vec < Vec < u8 > > > , mmaps : UnsafeCell < Vec < Mmap > > , } impl Stash { pub fn new () -> Stash { Stash { buffers : UnsafeCell :: new (Vec :: new ()) , mmaps : UnsafeCell :: new (Vec :: new ()) , } } #[doc = " Allocates a buffer of the specified size and returns a mutable reference"] #[doc = " to it."] pub fn allocate (& self , size : usize) -> & mut [u8] { let buffers = unsafe { & mut * self . buffers . get () } ; let i = buffers . len () ; buffers . push (vec ! [0 ; size]) ; & mut buffers [i] } #[doc = " Stores a `Mmap` for the lifetime of this `Stash`, returning a pointer"] #[doc = " which is scoped to just this lifetime."] pub fn cache_mmap (& self , map : Mmap) -> & [u8] { unsafe { let mmaps = & mut * self . mmaps . get () ; mmaps . push (map) ; mmaps . last () . unwrap () } } }